      SUBROUTINE RSTORCCC     TRANSFERS MATRIX RS TO RCCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'RC.CIN'      INCLUDE 'RS.CIN'      INCLUDE 'TC.CIN'      INCLUDE 'TS.CIN'      INCLUDE 'UC.CIN'      INCLUDE 'US.CIN'C      DO 10 JK = 1, 36   10 RCL(JK) = RSL(JK)      IF (NORD2 .GE. 2) THEN        DO 20 JKM = 1, 105   20   TCL(JKM) = TSL(JKM)      ENDIF      IF (NORD2 .GE. 3) THEN        DO 30 JKLM = 1, 280   30   UCL(JKLM) = USL(JKLM)      ENDIF      RETURN      END